function safe(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function campus(id){return st.campuses.find(x=>x.id===id)?.name||"Campus not found"}function campusAddress(id){const c=st.campuses.find(x=>x.id===id);return c?(c.address||c.city||"Address not provided"):"Campus not found"}function klass(id){return st.classes.find(x=>x.id===id)?.name||"Class not found"}function date(v){try{let d=v?.toDate?v.toDate():v?new Date(v):null;return d?d.toLocaleString():"Just now"}catch{return"Date unavailable"}}function rec(a,b,c){return'<div class="record"><div><b>'+safe(a)+'</b><small>'+safe(b)+'</small></div><span>'+safe(c)+'</span></div>'}function initials(name){return String(name||"User").trim().split(/\s+/).slice(0,2).map(x=>x[0]||"").join("").toUpperCase()||"U"}function avatarMarkup(person){const photo=person?.photoDataUrl||person?.photoURL||"";return photo?'<img class="person-avatar" src="'+safe(photo)+'" alt="'+safe(person?.name||"Profile photo")+'" loading="lazy">' : '<span class="person-avatar person-avatar-fallback" aria-hidden="true">'+safe(initials(person?.name))+'</span>'}function renderStaffDirectory(){const groups=[["owner","staff-owners","No institution owner profile found."],["institution_admin","staff-institution-admins","No institution administrators found."],["campus_admin","staff-campus-admins","No campus administrators found."],["lecturer","staff-lecturers","No lecturers found."]];groups.forEach(([roleKey,id,empty])=>{const box=$("#"+id);if(!box)return;const people=st.members.filter(m=>m.role===roleKey).sort((x,y)=>String(x.name||"").localeCompare(String(y.name||"")));box.className=people.length?"staff-list":"staff-list empty";box.innerHTML=people.length?people.map(m=>{const assignedCampusId=m.assignedCampusId||m.campusId||"";const assignedCampus=assignedCampusId?campus(assignedCampusId):"Campus not assigned";return '<div class="staff-person">'+avatarMarkup(m)+'<div class="staff-person-details"><b>'+safe(m.name||"Name unavailable")+'</b><small style="display:block">'+safe(m.email||"Email not available")+'</small><small style="display:block">Campus: '+safe(assignedCampus)+"</small></div></div>"}).join(""):empty;});}
