function studentSessionQueryRefs(enrolments,learner,campusId){
 const refs=[],seen=new Set();
 for(const en of enrolments||[]){
  if(en.status!=="active"||!en.courseUnitId||!en.academicYearId||!en.studyYear||!en.semesterId||!campusId||en.campusId!==campusId)continue;
  const base=[where("campusId","==",campusId),where("courseUnitId","==",en.courseUnitId),where("academicYearId","==",en.academicYearId)];
  const classId=learner?.classId||"";
  if(classId){
   const cohortKey=String(en.studyYear)+"__"+String(en.academicYearId)+"__"+String(en.semesterId),classBase=[...base,where("classId","==",classId),where("cohortKeys","array-contains",cohortKey)];
   const classCombined=JSON.stringify(["class",campusId,en.courseUnitId,classId,cohortKey]);
   if(!seen.has(classCombined)){seen.add(classCombined);refs.push(query(col("sessions"),...classBase,where("sessionGroupMode","==","combined")));}
  }
  const cohortKey=String(en.studyYear)+"__"+String(en.academicYearId)+"__"+String(en.semesterId);
  const common=[...base,where("cohortKeys","array-contains",cohortKey)];
  const combinedKey=JSON.stringify(["combined",campusId,en.courseUnitId,cohortKey]);
  if(!seen.has(combinedKey)){seen.add(combinedKey);refs.push(query(col("sessions"),...common,where("sessionGroupMode","==","combined")));}
  if(en.teachingGroupId){
   const groupKey=JSON.stringify(["separate",campusId,en.courseUnitId,cohortKey,en.teachingGroupId]);
   if(!seen.has(groupKey)){seen.add(groupKey);refs.push(query(col("sessions"),...common,where("sessionGroupMode","==","separate"),where("teachingGroupId","==",en.teachingGroupId)));}
  }
 }
 return refs;
}
async function fetchStudentSessions(enrolments,learner,campusId){const uid=st.user.uid,id=st.profile.institutionId;const feed=await getDocs(collection(db,"institutions",id,"studentSessionFeeds",uid,"sessions"));const docs=await Promise.all(feed.docs.map(x=>getDoc(doc(db,"institutions",id,"sessions",x.id))));return docs.filter(x=>x.exists()).map(x=>({id:x.id,...x.data()})).filter(s=>s.campusId===campusId&&(enrolments||[]).some(en=>sessionMatchesEnrolment(s,en,learner?.classId)))}
async function publishSessionToStudentFeeds(sessionId,session){
 const ids=new Set();
 for(const en of st.enrolments||[]){const uid=en.studentUid||en.authUid,student=st.students.find(x=>x.id===uid||x.authUid===uid);if(en.status==="active"&&student&&student.status!=="inactive"&&student.campusId===session.campusId&&sessionMatchesEnrolment(session,en,student.classId))ids.add(uid)}
 const list=[...ids],institutionId=st.profile.institutionId,createdBy=st.user.uid;
 // Keep writes independent: Firestore security-rule document lookups are evaluated per write.
 for(let offset=0;offset<list.length;offset+=20){await Promise.all(list.slice(offset,offset+20).map(studentUid=>setDoc(doc(db,"institutions",institutionId,"studentSessionFeeds",studentUid,"sessions",sessionId),{sessionId,campusId:session.campusId,courseUnitId:session.courseUnitId,createdBy,createdAt:serverTimestamp()})));}
 return list.length;
}
function sessionHasEnded(s){return s.status==="closed"||Number(s.expiresAt)<=Date.now()}
function sessionMatchesEnrolment(s,en,studentClassId=""){
 if(!s||!en||en.status!=="active")return false;
 if(String(s.courseUnitId||"")!==String(en.courseUnitId||"")||String(s.campusId||"")!==String(en.campusId||""))return false;
 const isClass=s.sessionType==="class"||(!s.sessionType&&!!s.classId);
 const value=v=>String(v??"");
 if(isClass){
  if(s.programmeId&&value(s.programmeId)!==value(en.programmeId))return false;
  if(!s.programmeId&&s.classId&&studentClassId&&value(s.classId)!==value(studentClassId))return false;
  if(s.academicYearId&&value(s.academicYearId)!==value(en.academicYearId))return false;
  const years=(Array.isArray(s.studyYears)&&s.studyYears.length?s.studyYears:[s.studyYear].filter(Boolean)).map(value);
  const semesters=(Array.isArray(s.semesterIds)&&s.semesterIds.length?s.semesterIds:[s.semesterId].filter(Boolean)).map(value);
  const cohortKey=value(en.studyYear)+"__"+value(en.academicYearId)+"__"+value(en.semesterId);
  const keys=(Array.isArray(s.cohortKeys)&&s.cohortKeys.length?s.cohortKeys:[cohortKey]).map(value);
  return (!years.length||years.includes(value(en.studyYear)))&&(!semesters.length||semesters.includes(value(en.semesterId)))&&keys.includes(cohortKey);
 }
 const cohortKey=value(en.studyYear)+"__"+value(en.academicYearId)+"__"+value(en.semesterId);
 const keys=(Array.isArray(s.cohortKeys)?s.cohortKeys:[]).map(value);
 const years=(Array.isArray(s.studyYears)&&s.studyYears.length?s.studyYears:[s.studyYear].filter(Boolean)).map(value);
 const semesters=(Array.isArray(s.semesterIds)&&s.semesterIds.length?s.semesterIds:[s.semesterId].filter(Boolean)).map(value);
 const cohortMatch=keys.length?keys.includes(cohortKey):value(s.academicYearId)===value(en.academicYearId)&&years.includes(value(en.studyYear))&&semesters.includes(value(en.semesterId));
 return cohortMatch&&(s.sessionGroupMode==="combined"||value(s.teachingGroupId||"")===value(en.teachingGroupId||""));
}
function renderStudentCourseAnalytics(){
 const box=$("#student-course-analytics");if(!box)return;
 const present=new Set((st.attendanceHistory||[]).filter(a=>a.status==="present").map(a=>a.sessionId));
 const learner=st.students.find(x=>x.authUid===st.user?.uid||x.id===st.user?.uid)||st.students[0];
 const enrolments=(st.enrolments||[]).filter(en=>en.status==="active");
 const rows=enrolments.map(en=>{
  const sessions=[...new Map((st.sessions||[]).filter(s=>sessionMatchesEnrolment(s,en,learner?.classId)&&sessionHasEnded(s)).map(s=>[s.id,s])).values()];
  const attended=sessions.filter(s=>present.has(s.id)).length;
  return {name:st.courseUnits.find(c=>c.id===en.courseUnitId)?.name||en.courseUnitId,attended,total:sessions.length,rate:sessions.length?Math.round(attended/sessions.length*100):null};
 });
 const classSessions=[...new Map((st.sessions||[]).filter(s=>sessionHasEnded(s)&&(s.courseUnitId?enrolments.some(en=>sessionMatchesEnrolment(s,en,learner?.classId)):s.classId===learner?.classId&&s.campusId===learner?.campusId)).map(s=>[s.id,s])).values()];
 if(classSessions.length){const attended=classSessions.filter(s=>present.has(s.id)).length;rows.push({name:"Overall class attendance",attended,total:classSessions.length,rate:Math.round(attended/classSessions.length*100)})}
 box.className=rows.length?"surface pale":"empty";
 box.innerHTML=rows.length?'<h3>Attendance percentages</h3>'+rows.map(x=>'<div class="record"><div><b>'+safe(x.name)+'</b><small>'+x.attended+' attended out of '+x.total+' eligible sessions</small></div><strong>'+(x.rate===null?"No sessions yet":x.rate+"%")+'</strong></div>').join(""):"No completed attendance opportunities yet.";
}
async function renderAttendanceAnalytics(){
 const box=$("#attendance-analytics");if(!box)return;
 box.textContent="Calculating attendance percentages…";
 try{
  let records=[];
  if(["owner","institution_admin"].includes(role())){const [snap,absenceSnap]=await Promise.all([getDocs(col("attendance")),getDocs(col("absences"))]);records=[...snap.docs,...absenceSnap.docs].map(d=>({id:d.id,...d.data()}))}
  else{const snaps=await Promise.all(st.sessions.map(s=>Promise.all([getDocs(query(col("attendance"),where("sessionId","==",s.id))),getDocs(query(col("absences"),where("sessionId","==",s.id)))])));records=snaps.flatMap(pair=>pair.flatMap(s=>s.docs.map(d=>({id:d.id,...d.data()}))))}
  const bySession=new Map();records.forEach(r=>{if(!bySession.has(r.sessionId))bySession.set(r.sessionId,[]);bySession.get(r.sessionId).push(r)});
  const groups=new Map();
  const add=(key,label,eligible,present)=>{if(!groups.has(key))groups.set(key,{label,eligible:0,present:0});const g=groups.get(key);g.eligible+=eligible;g.present+=present};
  let totalEligible=0,totalPresent=0;
  for(const s of st.sessions.filter(sessionHasEnded)){
   const eligible=s.courseUnitId
    ?st.enrolments.filter(en=>sessionMatchesEnrolment(s,en,st.students.find(x=>x.id===(en.studentUid||en.authUid))?.classId))
    :st.students.filter(x=>x.status!=="inactive"&&x.classId===s.classId&&x.campusId===s.campusId);
   const uniqueEligible=[...new Map(eligible.map(en=>{const uid=en.studentUid||en.authUid||en.id;return [uid,{...en,studentUid:uid}]})).values()];
   if(!uniqueEligible.length)continue;
   const ids=new Set(uniqueEligible.map(x=>x.studentUid));
   const present=new Set((bySession.get(s.id)||[]).filter(r=>r.status==="present"&&ids.has(r.studentId)).map(r=>r.studentId));
   const p=present.size,e=uniqueEligible.length;totalEligible+=e;totalPresent+=p;
   if(s.courseUnitId){
    add("unit:"+s.courseUnitId,"Course unit · "+(st.courseUnits.find(c=>c.id===s.courseUnitId)?.name||s.courseUnitId),e,p);
    const byClass=new Map();
    for(const en of uniqueEligible){const learner=st.students.find(x=>x.id===en.studentUid),classId=learner?.classId||"";if(!classId)continue;if(!byClass.has(classId))byClass.set(classId,{eligible:0,present:0});const group=byClass.get(classId);group.eligible++;if(present.has(en.studentUid))group.present++}
    for(const [classId,group] of byClass)add("class:"+classId,"Class · "+klass(classId),group.eligible,group.present);
   }else add("class:"+s.classId,"Class · "+klass(s.classId),e,p);
   add("campus:"+s.campusId,"Campus · "+campus(s.campusId),e,p);
  }
  const rows=[{label:"Overall attendance",eligible:totalEligible,present:totalPresent},...groups.values()];
  box.className=rows.length>1?"surface pale":"empty";
  box.innerHTML=rows.length>1?'<h2>Attendance percentages</h2><p class="tiny">Present learner-session opportunities divided by all eligible learner-session opportunities. Shared course units include every selected study year and semester and respect the session-group setting.</p>'+rows.map(g=>'<div class="record"><div><b>'+safe(g.label)+'</b><small>'+g.present+' present out of '+g.eligible+' eligible opportunities</small></div><strong>'+Math.round(g.present/g.eligible*100)+'%</strong></div>').join(""):"No completed sessions with eligible learners are available for analysis.";
 }catch(e){box.className="empty";box.textContent="Attendance analytics could not be loaded: "+err(e)}
}
