$("#bulk-promotion-form")?.addEventListener("submit",async e=>{e.preventDefault();if(!manage())return msg("promotion-message","Only institution owners, institution administrators and campus administrators can run bulk promotion.");const programmeId=$("#promotion-programme").value,fromYear=$("#promotion-from-year").value,currentSemesterId=$("#promotion-current-semester").value,targetYear=$("#promotion-target-year").value,academicYearId=$("#promotion-academic-year").value,semesterId=$("#promotion-semester").value,semester=st.semesters.find(x=>x.id===semesterId),semesterNumber=Number(semester?.semesterNumber)||Number(String(semester?.name||"").replace(/[^0-9]/g,""))||0;if(!programmeId||!fromYear||!currentSemesterId||!targetYear||!academicYearId||!semesterId)return msg("promotion-message","Choose the programme, current year, current semester, target year of study, target academic year and target semester.");const mappings=st.curriculumMappings.filter(x=>x.status!=="inactive"&&x.programmeId===programmeId&&String(x.studyYear)===String(targetYear)&&Number(x.semesterNumber)===semesterNumber),targetUnits=[...new Set(mappings.map(x=>x.courseUnitId))];if(!targetUnits.length)return msg("promotion-message","No active curriculum units are mapped for "+targetYear+", semester "+semesterNumber+". Set up the target curriculum first.");const invalid=targetUnits.filter(id=>!st.courseUnits.some(u=>u.id===id&&u.status==="active"&&(u.programmeIds||[]).includes(programmeId)));if(invalid.length)return msg("promotion-message","The target curriculum contains inactive or unlinked course units. Correct the curriculum before promoting.");const learners=st.students.filter(s=>s.status!=="inactive"&&s.programmeId===programmeId&&String(s.studyYear)===String(fromYear)&&st.enrolments.some(en=>en.studentUid===s.id&&en.status==="active"&&en.semesterId===currentSemesterId&&en.programmeId===programmeId));if(!learners.length)return msg("promotion-message","No active learners were found in that programme and year.");const targetLabel=semester.name+" ("+targetYear+")";if(!confirm("Promote "+learners.length+" learner(s) from "+fromYear+" to "+targetLabel+"? Their active course-unit enrolments will be replaced using the mapped target curriculum. Attendance history will not be changed."))return;const button=e.submitter;if(button)button.disabled=true;let done=0,failed=[];try{for(const learner of learners){try{const previous=st.enrolments.filter(en=>en.studentUid===learner.id&&en.status==="active"),previousByUnit=new Map(previous.map(en=>[en.courseUnitId,en])),batch=writeBatch(db),now=Date.now();let n=0;for(const old of previous){batch.set(doc(col("enrolmentHistory"),learner.id+"_"+old.courseUnitId+"_promotion_"+now+"_"+(n++)),{...old,archivedAt:serverTimestamp(),archivedBy:st.user.uid,archiveReason:"academic-year-promotion"});if(targetUnits.includes(old.courseUnitId)){batch.update(doc(col("enrolments"),old.id),{programmeId,studyYear:targetYear,academicYearId,semesterId,campusId:learner.campusId,teachingGroupId:learner.teachingGroupId||"",status:"active",updatedAt:serverTimestamp(),updatedBy:st.user.uid});}else{batch.update(doc(col("enrolments"),old.id),{status:"inactive",endedAt:serverTimestamp(),endedBy:st.user.uid,updatedAt:serverTimestamp(),updatedBy:st.user.uid});}}for(const unitId of targetUnits){if(!previousByUnit.has(unitId)){batch.set(doc(col("enrolments"),learner.id+"_"+unitId),{studentUid:learner.id,courseUnitId:unitId,programmeId,studyYear:targetYear,academicYearId,semesterId,enrollmentYear:learner.enrollmentYear||null,campusId:learner.campusId,teachingGroupId:learner.teachingGroupId||"",status:"active",createdAt:serverTimestamp(),createdBy:st.user.uid});}}batch.update(doc(col("students"),learner.id),{courseUnitIds:targetUnits,studyYear:targetYear,academicYearId,semesterId,updatedAt:serverTimestamp(),updatedBy:st.user.uid});await batch.commit();done++;}catch(error){failed.push((learner.name||learner.id)+": "+err(error));}}await refresh();if(failed.length)msg("promotion-message",done+" learner(s) promoted. "+failed.length+" failed: "+failed.slice(0,3).join(" | "));else msg("promotion-message","Successfully promoted "+done+" learner(s) to "+targetLabel+". Previous enrolments were archived; attendance history was not changed.",true);}catch(error){msg("promotion-message",done+" learner(s) promoted before an error: "+err(error));}finally{if(button)button.disabled=false}});

function bindAcademicEditor(selectId,collection,stateKey,formId,fields,buttonLabel,messageId,makeMessage){
 const select=$("#"+selectId);if(!select)return;
 select.addEventListener("change",()=>{const id=select.value;if(!id)return;const item=st[collection].find(x=>x.id===id);if(!item)return;st[stateKey]=id;for(const [field,key,format] of fields){const el=$("#"+field);if(el)el.value=format?format(item[key],item):item[key]??"";}const form=$("#"+formId);if(form){setTextNode(form.querySelector("button[type=submit],button.primary"),buttonLabel);form.scrollIntoView({behavior:"smooth",block:"center"});}msg(messageId,makeMessage(item),true);});
}
