document.addEventListener("click",async event=>{
 const button=event.target.closest("[data-archive-record]");if(!button)return;
 const collection=button.dataset.archiveRecord,recordId=button.dataset.id;
 const item=(st[collection]||[]).find(x=>x.id===recordId);if(!item)return;
 const label=({academicYears:"academic year",semesters:"semester",programmes:"programme",courseUnits:"course unit",curriculumMappings:"curriculum mapping",teachingGroups:"session"})[collection]||"record";
 const activeEnrolments=st.enrolments.filter(e=>(e.status||"active")==="active");
 const inUse=collection==="academicYears"?st.semesters.some(x=>x.academicYearId===recordId&&x.status!=="inactive")||activeEnrolments.some(e=>e.academicYearId===recordId)
 :collection==="semesters"?activeEnrolments.some(e=>e.semesterId===recordId)
 :collection==="programmes"?st.students.some(s=>s.programmeId===recordId&&(s.status||"active")==="active")||activeEnrolments.some(e=>e.programmeId===recordId)||st.courseUnits.some(u=>u.status!=="inactive"&&(u.programmeIds||[]).includes(recordId))
 :collection==="courseUnits"?activeEnrolments.some(e=>e.courseUnitId===recordId)
 :collection==="teachingGroups"?st.students.some(s=>s.teachingGroupId===recordId&&(s.status||"active")==="active")
 :false;
 const messageId=({academicYears:"academic-year-message",semesters:"semester-message",programmes:"programme-message",courseUnits:"course-unit-message",curriculumMappings:"curriculum-map-message",teachingGroups:"teaching-group-message"})[collection];
 if(inUse){msg(messageId,"This "+label+" is still used by active records. Reassign or complete those records before removing it.");return;}
 if(!confirm("Remove this "+label+" from active setup? Existing history will be retained."))return;
 button.disabled=true;
 try{await updateDoc(doc(col(collection),recordId),{status:"inactive",archivedAt:serverTimestamp(),archivedBy:st.user.uid});msg(messageId,label.charAt(0).toUpperCase()+label.slice(1)+" removed from active setup. Historical records retained.",true);await refresh();}
 catch(error){msg(messageId,err(error));button.disabled=false;}
});
function normaliseUniqueCode(value){return String(value||"").trim().toLocaleUpperCase().replace(/\\s+/g,"")}
function assertUniqueCode(records,field,value,excludeId,label){const normalised=normaliseUniqueCode(value);if(!normalised)return;const duplicate=(records||[]).some(record=>record.id!==excludeId&&normaliseUniqueCode(record[field])===normalised);if(duplicate)throw Error(label+" code "+String(value).trim()+" is already in use in this institution. Enter a different code.");}
async function uniqueActiveSessionCode(campusId,excludeSessionId=""){for(let attempt=0;attempt<20;attempt++){const candidate=code();if(st.sessions.some(session=>session.id!==excludeSessionId&&session.campusId===campusId&&session.status==="active"&&session.activeCode===candidate))continue;const snapshot=await getDocs(query(col("sessions"),where("campusId","==",campusId)));if(snapshot.docs.some(d=>d.id!==excludeSessionId&&d.data().status==="active"&&d.data().activeCode===candidate))continue;return candidate;}throw Error("Could not generate a unique session code. Please try again.");}
