function viewStateKey(){return "intercampus-view-"+(st.user?.uid||"guest")+"-"+(st.profile?.institutionId||"")};function panel(n){const allowed=new Set($$( ".nav[data-panel]:not(.hidden)" ).map(b=>b.dataset.panel));if(!allowed.has(n))n=role()==="student"?"sessions":"overview";$$( ".panel" ).forEach(hide);const next=$("#panel-"+n);if(next){show(next);next.scrollIntoView({behavior:"smooth",block:"start"})}$$( ".nav[data-panel]" ).forEach(b=>b.classList.toggle("active",b.dataset.panel===n));setSidebar(false);const workspace=$("#app-view .workspace");if(workspace)workspace.scrollTo({top:0,behavior:"smooth"});try{const saved=JSON.parse(localStorage.getItem(viewStateKey())||"{}");saved.panel=n;localStorage.setItem(viewStateKey(),JSON.stringify(saved))}catch{}if(n==="subscription")startBillingLiveUpdates();else stopBillingLiveUpdates()}$$( ".nav[data-panel]" ).forEach(b=>{if(!b.dataset.bound){b.dataset.bound="1";b.addEventListener("click",()=>{panel(b.dataset.panel);if(b.dataset.panel==="reports")renderAttendanceAnalytics();if(b.dataset.panel==="subscription")startBillingLiveUpdates()})}});document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>panel(b.dataset.go));
