let sessionDetailHome=null;function restoreSessionList(){stopActiveAttendanceSync();const detail=$("#active-session"),panelEl=$("#panel-sessions");if(sessionDetailHome)sessionDetailHome.appendChild(detail);hide(detail);["#qr-code","#live-code","#code-countdown","#attendance-roster","#close-session"].forEach(sel=>$(sel).classList.remove("hidden"));detail.querySelectorAll("small").forEach(el=>{if(el.textContent.includes("Current session code"))el.classList.remove("hidden")});panelEl.querySelector(".columns")?.classList.remove("hidden");$("#session-detail-back")?.remove();$("#active-student-attend")?.remove();if(st.timer){clearInterval(st.timer);st.timer=null}st.active=null;try{const saved=JSON.parse(localStorage.getItem(viewStateKey())||"{}");delete saved.activeSessionId;localStorage.setItem(viewStateKey(),JSON.stringify(saved))}catch{}}async function activate(id){st.active=st.sessions.find(s=>s.id===id);if(!st.active)return;try{const saved=JSON.parse(localStorage.getItem(viewStateKey())||"{}");saved.panel="sessions";saved.activeSessionId=id;localStorage.setItem(viewStateKey(),JSON.stringify(saved))}catch{}const detail=$("#active-session");if(!sessionDetailHome)sessionDetailHome=detail.parentElement;const columns=$("#panel-sessions .columns");columns.classList.add("hidden");$("#panel-sessions").appendChild(detail);detail.classList.remove("hidden");if(!$("#session-detail-back")){const back=document.createElement("button");back.id="session-detail-back";back.type="button";back.className="secondary";back.textContent="← Back to sessions";back.addEventListener("click",restoreSessionList);detail.prepend(back)}setText("#active-title",st.active.title);setText("#active-meta",campus(st.active.campusId)+" · "+(st.active.programmeId?(st.programmes.find(p=>p.id===st.active.programmeId)?.name||"Programme"):(st.active.classId?klass(st.active.classId):"Shared course unit"))+" · expires "+new Date(st.active.expiresAt).toLocaleTimeString());const studentView=role()==="student";["#qr-code","#live-code","#code-countdown","#attendance-roster","#close-session"].forEach(sel=>$(sel).classList.toggle("hidden",studentView));$("#active-session").querySelectorAll("small").forEach(el=>{if(el.textContent.includes("Current session code"))el.classList.toggle("hidden",studentView)});if(studentView&&!$("#active-student-attend")){const b=document.createElement("button");b.id="active-student-attend";b.type="button";b.className="primary";b.textContent="Mark attendance";b.addEventListener("click",()=>markOwnAttendance(id,b));$("#active-session").appendChild(b)}draw();startActiveAttendanceSync(id);$("#attendance-roster").textContent="Loading live attendance…";renderAttendanceRoster();if(st.timer)clearInterval(st.timer);const rotationInterval=30*60*1000;let nextRotationAt=(st.active.codeUpdatedAt||Date.now())+rotationInterval;st.timer=setInterval(async()=>{let s=st.active;if(!s||s.status!=="active")return;if(Date.now()>s.expiresAt){if(st.user.uid===s.createdBy){await close(true)}else{clearInterval(st.timer);st.timer=null;msg("session-message","Session duration elapsed. Only the session owner can close it.")}return}if(Date.now()>=nextRotationAt){const now=Date.now();nextRotationAt=now+60000;try{const next=await uniqueActiveSessionCode(s.campusId,s.id);await updateDoc(doc(db,"institutions",st.profile.institutionId,"sessions",s.id),{activeCode:next,codeUpdatedAt:now,codeVersion:(s.codeVersion||1)+1});s.activeCode=next;s.codeUpdatedAt=now;s.codeVersion=(s.codeVersion||1)+1;nextRotationAt=now+rotationInterval;await refresh()}catch(e){msg("attendance-message","QR rotation failed: "+err(e));}}draw()},1000)}
function renderAttendanceRoster(){const box=$("#attendance-roster");if(!box||!st.active||role()==="student")return;const learners=st.active.courseUnitId?st.enrolments.filter(en=>{const student=st.students.find(item=>item.id===en.studentUid||item.authUid===en.studentUid);return !!student&&student.status!=="inactive"&&sessionMatchesEnrolment(st.active,en,student.classId||"")}).map(en=>st.students.find(student=>student.id===en.studentUid||student.authUid===en.studentUid)).filter(Boolean):[];if(!learners.length){box.innerHTML='<p class="tiny">No active learners match this session’s course unit, programme, campus, study year, semester and session group.</p>';return}const records=[...(st.liveSessionAttendance||[]),...(st.liveSessionAbsences||[])],byStudent=new Map(records.map(a=>[a.studentId,a]));box.innerHTML='<h3>Attendance status · '+learners.length+' learners</h3>'+learners.map(s=>'<div class="record"><div><b>'+safe(s.name)+'</b><small>'+safe(s.studentNumber)+'</small></div><span>'+(byStudent.get(s.authUid||s.id)?.status==="present"?'Present ✓':byStudent.get(s.authUid||s.id)?.status==="absent"?'Absent ✕':'Not checked in')+'</span></div>').join('')}
function draw(){let s=st.active;if(!s)return;setText("#live-code",s.status==="closed"?"CLOSED":s.activeCode);$("#qr-code").innerHTML="";if(window.QRCode&&s.status==="active")new QRCode($("#qr-code"),{text:JSON.stringify({product:"InterCampusAttendance",institutionId:st.profile.institutionId,sessionId:s.id,code:s.activeCode,expiresAt:s.expiresAt}),width:145,height:145});else setText("#qr-code",s.status==="closed"?"Session closed":"Loading QR…");let left=Math.max(0,Math.ceil((s.expiresAt-Date.now())/1000));setText("#code-countdown",s.status==="closed"?"Closed":"Rotating session code · "+Math.floor(left/60)+"m "+left%60+"s left");}
$("#close-session").onclick=()=>close(false);async function finalizeSessionAbsences(s){
 if(!s||st.user.uid!==s.createdBy)throw Error("Only the session owner can finalize attendance.");
 const learners=s.courseUnitId
  ? st.enrolments.filter(en=>en.courseUnitId===s.courseUnitId&&en.campusId===s.campusId&&en.status==="active"&&(s.sessionType==="course-unit"?((s.studyYears||[s.studyYear]).includes(en.studyYear)&&(s.semesterIds||[s.semesterId]).includes(en.semesterId)&&en.academicYearId===s.academicYearId&&(s.sessionGroupMode==="combined"||(en.teachingGroupId||"")===(s.teachingGroupId||""))):en.programmeId===s.programmeId)).map(en=>({en,student:st.students.find(x=>x.id===en.studentUid)})).filter(x=>x.student&&x.student.status!=="inactive")
  : st.students.filter(x=>x.status!=="inactive"&&x.classId===s.classId&&x.campusId===s.campusId).map(student=>({student,en:null}));
 const [existingSnap,presentSnap]=await Promise.all([getDocs(query(col("absences"),where("sessionId","==",s.id))),getDocs(query(col("attendance"),where("sessionId","==",s.id)))]);
 const alreadyAbsent=new Set(existingSnap.docs.map(d=>d.data().studentId));
 const alreadyPresent=new Set(presentSnap.docs.map(d=>d.data().studentId));
 const missing=learners.filter(x=>{const uid=x.student.authUid||x.student.id;return !alreadyAbsent.has(uid)&&!alreadyPresent.has(uid)});
 for(let offset=0;offset<missing.length;offset+=400){
  const batch=writeBatch(db);
  for(const item of missing.slice(offset,offset+400)){
   const student=item.student,en=item.en,studentId=student.authUid||student.id;
   const data={sessionId:s.id,studentId,studentName:student.name||"",studentNumber:student.studentNumber||"",classId:student.classId||"",status:"absent",finalizedBy:st.user.uid,finalizedAt:serverTimestamp()};
   if(en)Object.assign(data,{courseUnitId:s.courseUnitId,programmeId:en.programmeId||"",studyYear:en.studyYear||"",academicYearId:en.academicYearId,semesterId:en.semesterId,teachingGroupId:en.teachingGroupId||"",enrolmentId:studentId+"_"+s.courseUnitId});
   batch.set(doc(db,"institutions",st.profile.institutionId,"absences",s.id+"_"+studentId),data);
  }
  await batch.commit();
 }
 return missing.length;
}
async function finalizeExpiredOwnedSessions(){
 if(role()==="student"||!st.user)return;
 for(const s of st.sessions.filter(x=>x.status==="active"&&x.createdBy===st.user.uid&&Number(x.expiresAt)<=Date.now())){
  try{
   const absentCount=await finalizeSessionAbsences(s);
   await updateDoc(doc(db,"institutions",st.profile.institutionId,"sessions",s.id),{status:"closed",closedAt:Date.now(),closedBy:st.user.uid});
   s.status="closed";s.activeCode=null;
   if(st.active?.id===s.id){st.active.status="closed";st.active.activeCode=null;draw()}
   msg("session-message","Session duration elapsed; closed. "+absentCount+" absent record(s) finalized.",true);
  }catch(e){console.warn("Expired session finalization will retry:",e);msg("session-message","Session expired. Finalization is pending; keep the session owner account online and try again. "+err(e))}
 }
}
