$("#student-checkin-form")?.addEventListener("submit",async e=>{
 e.preventDefault();
 const finishLoading=beginLoading("Verifying attendance, device and location…");
 const btn=$("#student-checkin-submit");if(btn)btn.disabled=true;
 const phase=label=>{const node=globalLoadingNode?.querySelector("#global-loading-label");if(node)node.textContent=label;};
 const checked=(promise,label)=>withTimeout(promise,15000,label+" is taking too long. Check your internet connection and try again.");
 try{
  const institutionId=st.profile.institutionId,sessionId=$("#checkin-session-id").value.trim(),code=$("#checkin-code").value.trim(),studentId=st.user.uid,deviceId=await deviceToken(st.user.uid);
  if(!/^\d{6}$/.test(code))throw Error("Enter the six-digit session code or scan the QR code.");
  phase("Checking your learner account and session…");
  const [studentSnap,sessionSnap]=await checked(Promise.all([getDoc(doc(db,"institutions",institutionId,"students",studentId)),getDoc(doc(db,"institutions",institutionId,"sessions",sessionId))]),"Account/session verification");
  if(!studentSnap.exists()||!sessionSnap.exists())throw Error("Your learner record or session was not found. Contact your administrator if this continues.");
  const student=studentSnap.data(),session=sessionSnap.data(),now=Date.now();
  if(student.authUid!==st.user.uid)throw Error("This learner record is not linked to your account.");
  if(student.status!=="active"||session.status!=="active"||now>=Number(session.expiresAt))throw Error("Your learner account or this session is inactive or expired.");
  let attendanceContext={classId:student.classId||""};
  if(session.courseUnitId){
   phase("Checking your course-unit enrolment…");
   const enrolmentSnap=await checked(getDoc(doc(db,"institutions",institutionId,"enrolments",studentId+"_"+session.courseUnitId)),"Course-unit enrolment verification");
   if(!enrolmentSnap.exists())throw Error("You are not enrolled in this course unit.");
   const enrolment=enrolmentSnap.data();
   if(!sessionMatchesEnrolment(session,enrolment,student.classId||""))throw Error("This session does not match your active course-unit enrolment. Check that your campus, course/programme, study year, academic year, semester and session group match the lecturer’s session.");
   attendanceContext={classId:student.classId||"",courseUnitId:session.courseUnitId,programmeId:enrolment.programmeId,studyYear:enrolment.studyYear||"",academicYearId:enrolment.academicYearId,semesterId:enrolment.semesterId,teachingGroupId:enrolment.teachingGroupId||"",enrolmentId:enrolmentSnap.id};
  }else if(student.classId!==session.classId||student.campusId!==session.campusId)throw Error("This session is not for your registered campus and class.");
  if(session.activeCode!==code||now-Number(session.codeUpdatedAt||0)>1860000)throw Error("The session code is incorrect or expired. Ask the lecturer to show the current code.");
  if(String(student.deviceId||"")!==String(deviceId||""))throw Error("This Chrome installation does not match the device registered to your learner account. Opening another tab in the same Chrome profile should not change device binding. Do not clear this site’s storage; contact your administrator to verify or reset the registered device if you changed browser profiles or website addresses.");
  phase("Checking your current location…");
  const position=await withTimeout(new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>resolve(p.coords),error=>{const messages={1:"Location permission was denied. Allow location access for this site in Chrome, then try again.",2:"Your location is unavailable. Turn on device location and try again.",3:"Location request timed out. Move to an area with a clearer GPS signal and try again."};reject(Error(messages[error.code]||"Could not verify your location."));},{enableHighAccuracy:true,timeout:12000,maximumAge:0}):reject(Error("This browser does not support location checks."))),16000,"Location verification timed out. Enable location and try again.");
  if(!Number.isFinite(position.latitude)||!Number.isFinite(position.longitude)||position.accuracy>100)throw Error("Location accuracy is too low. Enable precise location and try again outdoors.");
  if(session.requiresGps){
   if(!session.location)throw Error("This session has no saved classroom location. Ask the lecturer to reopen it with GPS enabled.");
   const distance=distanceMetres(position.latitude,position.longitude,session.location.latitude,session.location.longitude);
   if(distance>(session.radiusMeters||150))throw Error("You are "+Math.round(distance)+" metres from the classroom, outside the allowed "+(session.radiusMeters||150)+" metre radius.");
  }
  phase("Saving your attendance…");
  const attendanceRef=doc(db,"institutions",institutionId,"attendance",sessionId+"_"+studentId);
  if((await checked(getDoc(attendanceRef),"Existing attendance check")).exists())throw Error("Your attendance is already recorded for this session.");
  await checked(setDoc(attendanceRef,{sessionId,studentId,studentName:String(student.name||""),studentNumber:String(student.studentNumber||student.studentRegistrationNumber||student.admissionNumber||""),...attendanceContext,courseUnitName:st.courseUnits.find(c=>c.id===session.courseUnitId)?.name||"",status:"present",deviceId,code,location:new GeoPoint(position.latitude,position.longitude),accuracyMeters:position.accuracy,checkedAt:serverTimestamp()}),"Attendance save");
  msg("student-checkin-message","Attendance recorded for "+session.title+".",true);
  restoreCheckinScreen();await checked(refresh(),"Attendance screen refresh");
 }catch(e){console.error("Student attendance check-in failed",e);msg("student-checkin-message",err(e)+(e?.code?" ["+e.code+"]":""))}
 finally{if(btn)btn.disabled=false;finishLoading()}
});

/* Consistent progress feedback for all async screens and submissions. */
let globalLoadingCount=0,globalLoadingNode=null;
function beginLoading(label="Please wait…"){if(!globalLoadingNode){globalLoadingNode=document.createElement("div");globalLoadingNode.id="global-loading";globalLoadingNode.className="global-loading hidden";globalLoadingNode.setAttribute("role","status");globalLoadingNode.setAttribute("aria-live","polite");globalLoadingNode.innerHTML='<div class="loading-card"><span class="loading-spinner"></span><b id="global-loading-label">Please wait…</b></div>';document.body.appendChild(globalLoadingNode)}globalLoadingCount++;const loadingLabel=globalLoadingNode.querySelector("#global-loading-label");if(loadingLabel)loadingLabel.textContent=label;show(globalLoadingNode);let ended=false,watchdog;const finish=()=>{if(ended)return;ended=true;clearTimeout(watchdog);globalLoadingCount=Math.max(0,globalLoadingCount-1);if(!globalLoadingCount)hide(globalLoadingNode)};watchdog=setTimeout(finish,25000);return finish}
function wrapAsyncHandler(target,key,label){if(!target||typeof target[key]!=="function"||target[key].__loadingWrapped)return;const original=target[key];const wrapped=async function(...args){const finish=beginLoading(label);try{return await original.apply(this,args)}finally{finish()}};wrapped.__loadingWrapped=true;target[key]=wrapped}
document.querySelectorAll("form").forEach(form=>wrapAsyncHandler(form,"onsubmit","Processing your request…"));
["#auth-form","#setup-form","#join-registration-form","#campus-form","#class-form","#student-form","#member-form","#session-form"].forEach(sel=>{const f=$(sel);if(f)wrapAsyncHandler(f,"onsubmit",sel==="#auth-form"?"Signing you in…":sel==="#setup-form"?"Creating your institution workspace…":"Saving your changes…")});
["#forgot","#export-pdf","#close-session"].forEach(sel=>{const b=$(sel);if(b)wrapAsyncHandler(b,"onclick",sel==="#forgot"?"Sending password reset…":sel==="#export-pdf"?"Preparing your report…":"Closing attendance session…")});
const originalStart=start;start=async function(...args){const finish=beginLoading("Loading your institution workspace…");try{return await originalStart.apply(this,args)}finally{finish()}};
window.addEventListener("error",event=>{console.error("InterCampus portal runtime error",event.error||event.message);const target=$("#auth-view")&&!$("#auth-view").classList.contains("hidden")?"auth-message":"report-message";if(event.message)msg(target,"The portal encountered a script error. Refresh the page; if it continues, contact support and share this message: "+String(event.message).slice(0,180))});window.addEventListener("unhandledrejection",event=>{console.error("InterCampus portal async error",event.reason);const target=$("#auth-view")&&!$("#auth-view").classList.contains("hidden")?"auth-message":"report-message";const detail=event.reason?.message||String(event.reason||"Unknown error");msg(target,"A portal operation failed: "+detail.slice(0,180))});
const authLoadingFinish=beginLoading("Checking your sign-in…");
const authLoadingWatch=setInterval(()=>{if($("#app-view")&&!$("#app-view").classList.contains("hidden")||$("#auth-view")&&!$("#auth-view").classList.contains("hidden")||$("#setup-view")&&!$("#setup-view").classList.contains("hidden")||$("#join-registration-view")&&!$("#join-registration-view").classList.contains("hidden")){authLoadingFinish();clearInterval(authLoadingWatch)}},250);

window.__interCampusBootReady=true;clearTimeout(window.__interCampusBootTimer);